  'keychain.storeUnreadable': 'تعذّر على GitHuttBr قراءة رموزك المحفوظة — كانت سلسلة المفاتيح مقفلة أو رُفض الوصول. لم يُمسّ شيء منها. افتح قفل سلسلة المفاتيح وأعد المحاولة؛ الرموز التي تضيفها في الأثناء تُحفَظ فقط حتى تغلق التطبيق.',
  'keychain.weakBackend': 'لا توجد سلسلة مفاتيح قيد التشغيل (GNOME Keyring أو KWallet)، لذا يستخدم النظام التخزين الأساسي، الذي يكتفي بتمويه البيانات بكلمة مرور ثابتة بدل حمايتها. تبقى الرموز التي حفظتها سابقًا قابلة للقراءة، لكن الرموز الجديدة تُحفظ فقط حتى تغلق التطبيق؛ وتواصل الخزنة الحفظ هناك. ثبّت سلسلة مفاتيح أو افتح قفلها، ثم أعد تشغيل GitHuttBr.',
